Part 2/2, append directly after part 1:

```html
  const status = document.getElementById('status');

  let commits = []; // up to 2: [{divisor}] first = original, second = correction

  function announce(msg){ status.textContent = msg; }

  function el(tag, attrs, children){
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    (children||[]).forEach(c => e.appendChild(c));
    return e;
  }
  function text(x,y,str,cls){
    const t = el('text', {x, y, 'text-anchor':'middle', 'dominant-baseline':'middle', class: cls||''});
    t.textContent = str;
    return t;
  }

  function commit(rawValue){
    if (commits.length >= 2) return;
    const divisor = Number(rawValue);
    if (!Number.isInteger(divisor) || divisor < 1 || divisor > 12){
      announce('"' + rawValue + '" — не целое число от 1 до 12, узел не завязан. Поле оставлено как есть.');
      return;
    }
    if (TOTAL % divisor !== 0){ announce('84 не делится на ' + divisor + ' без остатка — узел не завязан.'); return; }
    commits.push({ divisor });
    render();
    if (commits.length === 1){
      announce('Узел ÷' + divisor + ' завязан: ' + divisor + ' доли по ' + (TOTAL/divisor) + '.');
    } else {
      announce('Внесена поправка: ÷' + divisor + ', ' + divisor + ' доли по ' + (TOTAL/divisor) + '. Старый узел ÷' + commits[0].divisor + ' остался историей сбоку.');
      tieBtn.disabled = true; input.disabled = true; chip.setAttribute('aria-disabled','true');
      const firstBead = svg.querySelector('[data-active-bead]');
      if (firstBead) firstBead.focus();
    }
    resetBtn.disabled = false;
  }

  function resetAll(){
    commits = [];
    tieBtn.disabled = false; input.disabled = false; chip.removeAttribute('aria-disabled');
    resetBtn.disabled = true;
    input.value = 4;
    render();
    announce('Начато заново. 84 жетона, узел ещё не завязан.');
  }

  function fan(cx, cy, n, spread){
    const pts = [];
    if (n === 1) { pts.push({x:cx,y:cy}); return pts; }
    const start = cx - spread/2;
    const step = spread/(n-1);
    for (let i=0;i<n;i++) pts.push({x: start + step*i, y: cy});
    return pts;
  }

  function drawBead(cx,cy,label,cls,onActivate){
    const attrs = { class:'bead', tabindex:'0', role:'button', 'aria-label': label + (onActivate?', нажмите Enter чтобы увидеть путь':'') };
    if (onActivate) attrs['data-active-bead'] = '1';
    const g = el('g', attrs);
    g.appendChild(el('circle', {cx,cy,r:18,class:cls}));
    g.appendChild(text(cx,cy,label,cls));
    if (onActivate){
      g.addEventListener('click', onActivate);
      g.addEventListener('keydown', (e)=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); onActivate(); } });
    }
    return g;
  }

  function clearHighlight(){
    svg.querySelectorAll('.path-highlight').forEach(n=>n.classList.remove('path-highlight'));
    svg.querySelectorAll('.knot-tip').forEach(n=>n.remove());
  }

  function render(){
    svg.innerHTML = '';
    const sx = 240, sy = 26;
    svg.appendChild(el('circle', {cx:sx, cy:sy, r:20, class:'bead-active'}));
    svg.appendChild(text(sx, sy, TOTAL, 'bead-active'));

    if (commits.length === 0){
      svg.appendChild(el('line', {x1:sx,y1:sy+20,x2:sx,y2:90,class:'thread'}));
      const zone = el('rect', {x:sx-30,y:90,width:60,height:36,rx:8,class:'tiezone', id:'tz'});
      svg.appendChild(zone);
      svg.appendChild(text(sx, 108, '?', 'tag'));
      setupDrop(zone, sx, 108);
      return;
    }

    // main (current) knot = last commit; history = earlier commits
    const activeIdx = commits.length - 1;
    const active = commits[activeIdx];
    const activeShare = TOTAL / active.divisor;
    const hasHistory = commits.length === 2;
    const kx = hasHistory ? sx - 55 : sx, ky = 100;

    svg.appendChild(el('line', {x1:sx,y1:sy+20,x2:kx,y2:ky-14,class:'thread', id:'mainline'}));
    const knotG = el('g', {});
    knotG.appendChild(el('circle', {cx:kx,cy:ky,r:16,class:'knot-active'}));
    knotG.appendChild(text(kx,ky,'÷'+active.divisor,'knot-active'));
    svg.appendChild(knotG);

    const pts = fan(kx, ky+70, active.divisor, Math.min(hasHistory ? 190 : 340, active.divisor*70));
    const beadLines = [];
    pts.forEach(p=>{
      const ln = el('line', {x1:kx,y1:ky+14,x2:p.x,y2:p.y-18,class:'thread'});
      svg.appendChild(ln);
      beadLines.push(ln);
    });
    pts.forEach((p,i)=>{
      const bead = drawBead(p.x,p.y, activeShare, 'bead-active', ()=>{
        clearHighlight();
        svg.querySelector('#mainline').classList.add('path-highlight');
        beadLines[i].classList.add('path-highlight');
        if (commits.length === 2){
          const tip = el('g', {class:'knot-tip'});
          tip.appendChild(text(kx, ky-28, 'поправлено: было ÷'+commits[0].divisor, 'tag'));
          svg.appendChild(tip);
        }
        announce('Путь: 84 → узел ÷' + active.divisor + ' → доля ' + activeShare + '.');
      });
      svg.appendChild(bead);
    });

    // second tie zone: where a correction knot can be dropped, once one knot exists
    if (commits.length === 1){
      const tzx = kx + 80, tzy = ky - 22;
      svg.appendChild(el('line', {x1:kx+14,y1:ky-8,x2:tzx-26,y2:tzy,class:'thread-history'}));
      const zone2 = el('rect', {x:tzx-26,y:tzy-15,width:52,height:30,rx:8,class:'tiezone', id:'tz2'});
      svg.appendChild(zone2);
      svg.appendChild(text(tzx, tzy, '±', 'tag'));
      setupDrop(zone2, tzx, tzy);
    }

    // history branch (only when there is a correction)
    if (commits.length === 2){
      const hist = commits[0];
      const histShare = TOTAL / hist.divisor;
      const hx = kx + 210, hy = ky;
      svg.appendChild(el('line', {x1:kx+14,y1:ky,x2:hx-12,y2:hy,class:'thread-history'}));
      const hg = el('g', { tabindex:'0', role:'button', 'aria-label':'история: было ÷'+hist.divisor+', не входит в текущую выдачу' });
      hg.appendChild(el('circle', {cx:hx,cy:hy,r:11,class:'knot-history'}));
      hg.appendChild(text(hx,hy,'÷'+hist.divisor,'knot-history'));
      svg.appendChild(hg);
      const hpts = fan(hx, hy+55, hist.divisor, Math.min(100, hist.divisor*24));
      hpts.forEach(p=>{
        svg.appendChild(el('line', {x1:hx,y1:hy+11,x2:p.x,y2:p.y-11,class:'thread-history'}));
        const g = el('g', {});
        g.appendChild(el('circle', {cx:p.x,cy:p.y,r:11,class:'bead-history'}));
        g.appendChild(text(p.x,p.y,histShare,'bead-history'));
        svg.appendChild(g);
      });
      svg.appendChild(text(hx, hy-20, 'история (заменено)', 'tag'));
      const showTip = ()=>announce('История: было ÷'+hist.divisor+', '+histShare+' на команду — в текущую выдачу не входит.');
      hg.addEventListener('click', showTip);
      hg.addEventListener('keydown', (e)=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); showTip(); } });
    }
  }

  function setupDrop(zone, cx, cy){
    zone.addEventListener('dragover', e=>{ e.preventDefault(); zone.classList.add('hover'); });
    zone.addEventListener('dragleave', ()=> zone.classList.remove('hover'));
    zone.addEventListener('drop', e=>{
      e.preventDefault(); zone.classList.remove('hover');
      commit(input.value);
    });
  }

  chip.addEventListener('dragstart', e=>{ chip.classList.add('dragging'); e.dataTransfer.setData('text/plain','tie'); });
  chip.addEventListener('dragend', ()=> chip.classList.remove('dragging'));
  chip.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); commit(input.value); } });
  tieBtn.addEventListener('click', ()=> commit(input.value));
  input.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); commit(input.value); } });
  resetBtn.addEventListener('click', resetAll);

  render();
})();
</script>
</body>
</html>

